import re
import json
import sys

def parse_script(text: str):
    nodes = []
    edges = []

    # Split by [NodeID] at the start of a line
    blocks = re.split(r'^\[(.*?)\]', text, flags=re.MULTILINE)

    # blocks[0] is everything before the first [NodeID]
    for i in range(1, len(blocks), 2):
        node_id = blocks[i].strip()
        content = blocks[i+1].strip()

        # Split content into lines and remove empty ones
        lines = [l.strip() for l in content.split('\n') if l.strip()]
        if not lines:
            nodes.append({"id": node_id, "text": "", "speaker": "", "type": "line"})
            continue

        # Determine if it's a choice node: any line starts with "1.", "2.", etc.
        is_choice = any(re.match(r'^\d+\.', l) for l in lines)

        if is_choice:
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            })
            for line in lines:
                # Match "N. Text -> Target"
                m = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
                if m:
                    choice_text = m.group(1).strip()
                    target = m.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            # Line node: Speaker: Text -> Target
            m = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(.*)$', lines[0])
            if m:
                nodes.append({
                    "id": node_id,
                    "text": m.group(2).strip(),
                    "speaker": m.group(1).strip(),
                    "type": "line"
                })
                edges.append({
                    "from": node_id,
                    "to": m.group(3).strip(),
                    "text": ""
                })
            else:
                # Fallback: Text -> Target
                m = re.match(r'^(.*?)\s*->\s*(.*)$', lines[0])
                if m:
                    nodes.append({
                        "id": node_id,
                        "text": m.group(1).strip(),
                        "speaker": "",
                        "type": "line"
                    })
                    edges.append({
                        "from": node_id,
                        "to": m.group(2).strip(),
                        "text": ""
                    })
                else:
                    # Just text
                    nodes.append({
                        "id": node_id,
                        "text": lines[0],
                        "speaker": "",
                        "type": "line"
                    })

    # Add missing nodes (like 'End') that are targeted but not defined
    node_ids = {n['id'] for n in nodes}
    for edge in edges:
        if edge['to'] not in node_ids:
            nodes.append({
                "id": edge['to'],
                "text": "",
                "speaker": "",
                "type": "line"
            })
            node_ids.add(edge['to'])

    return {"nodes": nodes, "edges": edges}

def main():
    try:
        with open('/app/script.txt', 'r') as f:
            content = f.read()
    except FileNotFoundError:
        return

    graph = parse_script(content)

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    # Generate DOT
    dot = ["digraph DialogueGraph {"]
    dot.append("    rankdir=LR;")
    dot.append("    node [shape=box, style=rounded];")
    for node in graph['nodes']:
        if node['type'] == 'choice':
            label = f"{node['id']}\\n(choice)"
        else:
            if node['speaker']:
                label = f"{node['speaker']}: {node['text']}"
            else:
                label = node['text'] if node['text'] else node['id']

        label = label.replace('"', '\\"')
        label = label.replace('\n', '\\n')
        dot.append(f'    "{node["id"]}" [label="{label}"];')

    for edge in graph['edges']:
        label = edge['text'].replace('"', '\\"')
        dot.append(f'    "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')

    dot.append("}")

    with open('/app/dialogue.dot', 'w') as f:
        f.write("\n".join(dot))

if __name__ == "__main__":
    main()
